class Solution {
    public int findNthDigit(int n){
        long position=n,digit=1,start=1,count=9;
        while(position>digit*count){
            position-=digit*count;
            digit++;
            start*=10;
            count*=10;
        }
        long number=start+(position-1)/digit;
        return String.valueOf(number).charAt((int)((position-1)%digit))-'0';
    }
}

code.kotlin:
class Solution {
    fun findNthDigit(n:Int):Int{
        var position=n.toLong();
        var digit=1L;
        var start=1L;
        var count=9L;
        while(position>digit*count){
            position-=digit*count;
            digit++;
            start*=10;
            count*=10
        };
        val number=start+(position-1)/digit;
        return number.toString()[((position-1)%digit).toInt()]-'0'
    }
}

